import tomllib


class ConfigError(Exception):
    pass


def coerce_value(key, value, expected_type):
    try:
        if expected_type is bool:
            if isinstance(value, bool):
                return value
            if str(value).lower() in ('true', '1', 'yes'):
                return True
            if str(value).lower() in ('false', '0', 'no'):
                return False
            raise ValueError
        return expected_type(value)
    except (ValueError, TypeError):
        raise ConfigError(f'Key {key} expected {expected_type}, got {type(value).__name__}')


def set_nested_value(obj, key_path, value):
    key = key_path
    if isinstance(obj, dict) and key in obj:
        obj[key] = value
    else:
        raise KeyError(f'Key {key} not found')


def load_config(defaults, toml_path=None, env_prefix='APP', env_map=None):
    config = defaults.copy()
    errors = []

    if toml_path and tomllib.toml.path(toml_path):
        try:
            with open(toml_path) as f:
                toml_data = tomllib.toml.path(f)
                for key, value in toml_data.items():
                    if key in config:
                        config[key] = value
        except FileNotFoundError:
            pass

    if env_map:
        for env_key, env_value in env_map.items():
            key_path = env_key
            if key_path in config:
                try:
                    config[key_path] = coerce_value(key_path, env_value, type(config[key_path]))
                except ConfigError as e:
                    errors.append(str(e))
            else:
                errors.append(f'Environment key {env_key} has no corresponding default')

    if errors:
        raise ConfigError('\\n        \".join(errors))

    return config

import pytest
from envcfg import load_config, ConfigError


def test_default_only():
    defaults = {"server": {"port": 8080}}
    config = load_config(defaults)
    assert config["server"]["port"] == 8080

def test_toml_override():
    defaults = {"server": {"port": 8080}}
    with open("test.toml", "w") as f:
        f.write('[server]
port = 9090')
    config = load_config(defaults, toml_path="test.toml")
    assert config["server"]["port"] == 9090
    import os
    os.remove("test.toml")

def test_env_override():
    defaults = {"server": {"port": 8080}}
    env = {"APP__SERVER__PORT": "9091"}
    config = load_config(defaults, env_map=env)
    assert config["server"]["port"] == 9091

def test_coerce_types():
    defaults = {"server": {"port": 8080}}
    env = {"APP__SERVER__PORT": "9092"}
    config = load_config(defaults, env_map=env)
    assert isinstance(config["server"]["port"], int)

def test_missing_toml():
    defaults = {"server": {"port": 8080}}
    config = load_config(defaults, toml_path="nonexistent.toml")
    assert config["server"]["port"] == 8080

def test_invalid_coerce():
    defaults = {"server": {"port": 8080}}
    env = {"APP__SERVER__PORT": "not-an-int"}
    with pytest.raises(ConfigError):
        load_config(defaults, env_map=env)

def test_unknown_env_key():
    defaults = {"server": {"port": 8080}}
    env = {"UNKNOWN": "value"}
    with pytest.raises(ConfigError):
        load_config(defaults, env_map=env)

